import{_ as o,o as t,c as a,a2 as n}from"./chunks/framework.ZymMlRuQ.js";const u=JSON.parse('{"title":"Coach Poulpy","description":"","frontmatter":{},"headers":[],"relativePath":"CONTEXT.md","filePath":"CONTEXT.md"}'),s={name:"CONTEXT.md"};function r(i,e,p,d,l,h){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="coach-poulpy" tabindex="-1">Coach Poulpy <a class="header-anchor" href="#coach-poulpy" aria-label="Permalink to &quot;Coach Poulpy&quot;">​</a></h1><p>A personal training platform where people build workouts, follow plans, train through guided sessions and watch their progress, coached by Poulpy, a reversible plush octopus.</p><h2 id="language" tabindex="-1">Language <a class="header-anchor" href="#language" aria-label="Permalink to &quot;Language&quot;">​</a></h2><h3 id="catalog-and-workouts" tabindex="-1">Catalog and workouts <a class="header-anchor" href="#catalog-and-workouts" aria-label="Permalink to &quot;Catalog and workouts&quot;">​</a></h3><p><strong>Exercise</strong>: One movement from the curated catalog, identified by a slug that never changes. <em>Avoid</em>: Move, drill</p><p><strong>Catalog</strong>: The curated, versioned set of exercises shipped with the app and updated without an account. <em>Avoid</em>: Exercise database, library (the library is the user&#39;s)</p><p><strong>Retired exercise</strong>: A catalog exercise no longer offered, kept so the workouts that use it still open. <em>Avoid</em>: Deleted exercise</p><p><strong>Variation</strong>: A catalog exercise that does the same movement made easier or harder, like the knee push-up and the diamond push-up for the push-up. Variations are equals in one group, ordered from easiest to hardest, and each keeps its own slug, records and history. <em>Avoid</em>: Progression, regression, alternative</p><p><strong>Alias</strong>: Another name people search an exercise by, like &quot;RDL&quot; or &quot;abdos&quot;, kept per language in the catalog and never shown. <em>Avoid</em>: Tag, keyword</p><p><strong>Format</strong>: How a workout is built, chosen when it is created and kept: a <strong>circuit</strong> goes round several exercises, each done once per round, so its exercises have no sets; <strong>sets</strong> does one exercise at a time, all its sets with a rest between them, then the next. <em>Avoid</em>: Workout type, kind, sport, category</p><p><strong>Workout</strong>: A versioned list of parts in one format, ready to be done. <em>Avoid</em>: Routine, program, training</p><p><strong>Part</strong>: One section of a workout, holding its steps: the warm-up (at most one, first), a work part (one or more, &quot;Work 1&quot;, &quot;Work 2&quot;), or the cool down (at most one, last). <em>Avoid</em>: Phase (a phase is one stretch of a timeline), block, section</p><p><strong>Step</strong>: One node of a part&#39;s tree: an exercise with its prescription, a group, or a rest. An exercise step has a role: exercise or recover; a rest is a recover step with no exercise. <em>Avoid</em>: Item, block</p><p><strong>Group</strong>: A step holding other steps: a sequence, superset, circuit or interval set with rounds. The builder calls the group it makes a <strong>Repeat</strong>: steps done a number of times, one level deep. <em>Avoid</em>: Block, round (a round is one pass through a group)</p><p><strong>Repeat</strong>: The builder&#39;s name for a group: &quot;Repeat 4 times&quot; around a run and a walk. It holds exercises and rests, never another repeat. <em>Avoid</em>: Loop, set (a set belongs to one exercise&#39;s prescription)</p><p><strong>Until button press</strong>: A walk or run&#39;s duration with no set amount: the step ends when the person taps Next. On the last step it reads <strong>until the end</strong>, and the tap finishes the session. <em>Avoid</em>: Lap, open-ended</p><p><strong>Prescription</strong>: What an exercise step asks for: its sets, and per set a target, load, intensity, tempo and the rest before the next set, none after the last. In a circuit an exercise holds one set, and the repeat around it does the rounds. <em>Avoid</em>: Target (a target is one part of a prescription), plan</p><h3 id="plans-and-scheduling" tabindex="-1">Plans and scheduling <a class="header-anchor" href="#plans-and-scheduling" aria-label="Permalink to &quot;Plans and scheduling&quot;">​</a></h3><p><strong>Plan</strong>: A versioned set of weeks, each day holding zero or more workouts, written out in full. <em>Avoid</em>: Program, schedule, routine</p><p><strong>Enrollment</strong>: One person following one version of a plan from a start date. <em>Avoid</em>: Subscription, assignment</p><p><strong>Calendar entry</strong>: One workout an enrollment schedules on a date, with a status: planned, done, skipped or moved. <em>Avoid</em>: Appointment, slot</p><p><strong>Planned workout</strong>: A workout a person put on a day themselves, outside any plan. <em>Avoid</em>: Scheduled session</p><p><strong>Goal</strong>: A measurable target with an optional deadline, whose progress is computed from sessions. <em>Avoid</em>: Objective</p><h3 id="training" tabindex="-1">Training <a class="header-anchor" href="#training" aria-label="Permalink to &quot;Training&quot;">​</a></h3><p><strong>Session</strong>: One workout actually done, from start to end, whether guided, free or recorded from a device only. <em>Avoid</em>: Execution, activity, workout log, training</p><p><strong>Session event</strong>: One thing that happened during a session (a phase started, a set logged, a pause, a sample), stored in order and never changed. <em>Avoid</em>: Log entry</p><p><strong>Timeline</strong>: The flat run of work, rest and transition phases a workout compiles to before a session runs it. A free recording&#39;s timeline is open-ended: it grows one manual phase each time the user ends a step, and the pause between two steps is their rest. <em>Avoid</em>: Playlist, sequence</p><p><strong>Phase</strong>: One stretch of a timeline with its own completion rule: manual, timer, distance or round count. Each phase knows the part it comes from; a part is not a phase. <em>Avoid</em>: Interval (an interval set is a group)</p><p><strong>Cue</strong>: A prompt the engine raises during a session (countdown, switch sides, next exercise) that each platform turns into sound, vibration or text. <em>Avoid</em>: Notification, alert</p><h3 id="devices" tabindex="-1">Devices <a class="header-anchor" href="#devices" aria-label="Permalink to &quot;Devices&quot;">​</a></h3><p><strong>Metric source</strong>: Anything that streams samples into a session; a treadmill today, a heart rate strap later. <em>Avoid</em>: Sensor, integration</p><p><strong>Sample</strong>: One timestamped reading from a metric source: speed, incline, distance, heart rate or cadence. <em>Avoid</em>: Data point, packet</p><h3 id="sharing-and-coaching" tabindex="-1">Sharing and coaching <a class="header-anchor" href="#sharing-and-coaching" aria-label="Permalink to &quot;Sharing and coaching&quot;">​</a></h3><p><strong>Library</strong>: A person&#39;s own workouts and plans, catalog items they kept, and items shared with them. <em>Avoid</em>: Collection, favourites</p><p><strong>Library entry</strong>: A shared workout or plan saved in a library, either synced to the author&#39;s latest version or as a copy. <em>Avoid</em>: Bookmark, fork</p><p><strong>Coach link</strong>: The tie an athlete grants a coach, which the athlete can revoke at any time. <em>Avoid</em>: Team, connection</p><h3 id="people" tabindex="-1">People <a class="header-anchor" href="#people" aria-label="Permalink to &quot;People&quot;">​</a></h3><p><strong>Guest</strong>: A person using the app with no account; everything stays on their phone. <em>Avoid</em>: Anonymous user, offline user</p><h3 id="poulpy" tabindex="-1">Poulpy <a class="header-anchor" href="#poulpy" aria-label="Permalink to &quot;Poulpy&quot;">​</a></h3><p><strong>Poulpy</strong>: The coach mascot, a reversible plush octopus: blue side when the plan is on track, ember side when a session slipped. <em>Avoid</em>: Avatar, character, octopus</p><p><strong>Mood</strong>: Poulpy&#39;s feeling, one of six shades: proud, happy, recovering on the blue side; annoyed, grumpy, fuming on the ember side. <em>Avoid</em>: State, emotion</p><p><strong>Pose</strong>: A full drawing of Poulpy for a moment that matters (Champion, Straining, Sleeping...), as opposed to a plain mood portrait. <em>Avoid</em>: Sticker, illustration</p><p><strong>Tentacle</strong>: One of the eight segments of Poulpy&#39;s ring; each finished session lights one, and a lit tentacle never goes dark. <em>Avoid</em>: Point, star, streak</p><p><strong>Full octopus</strong>: All eight tentacles lit, which shows the Champion pose and starts a new ring. <em>Avoid</em>: Level, badge</p>',44)])])}const g=o(s,[["render",r]]);export{u as __pageData,g as default};
